---
// The docs header: logo, the five topics as tabs, search, the version picker, and the site links.
import Search from '@astrojs/starlight/components/Search.astro';
import SiteTitle from '@astrojs/starlight/components/SiteTitle.astro';
import SocialIcons from '@astrojs/starlight/components/SocialIcons.astro';
import ThemeToggle from '../ThemeToggle.astro';
import VersionPicker from '../VersionPicker.astro';

// The 2.x archive has its own sidebar but no tab.
const topics = (Astro.locals.starlightSidebarTopics?.topics ?? []).filter((topic) => !topic.link.startsWith('/docs/2.x'));
---

<div class="mt-header">
	<div class="mt-header__row">
		<div class="title-wrapper sl-flex"><SiteTitle /></div>
		<div class="mt-header__search sl-flex print:hidden"><Search /></div>
		<div class="mt-header__right sl-hidden md:sl-flex print:hidden">
			<VersionPicker />
			<a class="mt-header__sponsor" href="/sponsor" aria-label="Sponsor Maester">
				<svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path fill="#db2777" d="M8 14.25s-6-3.6-6-8.1C2 3.8 3.7 2.5 5.4 2.5c1.2 0 2.1.7 2.6 1.6.5-.9 1.4-1.6 2.6-1.6 1.7 0 3.4 1.3 3.4 3.65 0 4.5-6 8.1-6 8.1z"></path></svg>
				Sponsor
			</a>
			<div class="sl-flex social-icons"><SocialIcons /></div>
			<ThemeToggle />
		</div>
	</div>
	<nav class="mt-tabs sl-hidden md:sl-flex" aria-label="Documentation sections">
		{
			topics.map((topic) => (
				<a href={topic.link} aria-current={topic.isCurrent ? 'page' : undefined} class:list={{ current: topic.isCurrent }}>
					{topic.label}
				</a>
			))
		}
		<a href="/" class="mt-tabs__home">Home</a>
	</nav>
</div>

<style is:global>
	/* The docs header lets the page show through, blurred, as it scrolls under: a tint of the nav colour and a
	   faint edge instead of a solid bar. Browsers without backdrop-filter get the solid colour. */
	header.header {
		background-color: var(--sl-color-bg-nav);
		border-bottom-color: color-mix(in srgb, var(--sl-color-hairline-shade) 55%, transparent);
	}
	@supports ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
		header.header {
			background-color: color-mix(in srgb, var(--sl-color-bg-nav) 72%, transparent);
			-webkit-backdrop-filter: saturate(180%) blur(14px);
			backdrop-filter: saturate(180%) blur(14px);
		}
	}
</style>

<style>
	.mt-header {
		display: flex;
		flex-direction: column;
		height: 100%;
		justify-content: center;
	}
	.mt-header__row {
		display: flex;
		align-items: center;
		gap: 1rem;
		justify-content: space-between;
	}
	.title-wrapper {
		overflow: clip;
		padding: 0.25rem;
		margin: -0.25rem;
		min-width: 0;
	}
	.mt-header__search {
		flex: 1 1 auto;
		justify-content: center;
	}
	.mt-header__right {
		gap: 0.9rem;
		align-items: center;
	}
	.social-icons {
		gap: 0.75rem;
		align-items: center;
	}
	.mt-header__sponsor {
		display: inline-flex;
		align-items: center;
		gap: 0.35rem;
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 9px;
		padding: 0.3rem 0.65rem;
		font-size: 0.8125rem;
		font-weight: 600;
		color: var(--sl-color-white);
		text-decoration: none;
	}
	.mt-header__sponsor:hover {
		border-color: var(--sl-color-gray-3);
	}
	.mt-tabs {
		gap: 1.5rem;
		align-items: flex-end;
		margin-top: 0.4rem;
		font-size: 0.875rem;
	}
	.mt-tabs a {
		color: var(--sl-color-gray-3);
		text-decoration: none;
		padding-bottom: 0.45rem;
		border-bottom: 2px solid transparent;
		font-weight: 500;
	}
	.mt-tabs a:hover {
		color: var(--sl-color-white);
	}
	.mt-tabs a.current {
		color: var(--sl-color-white);
		border-bottom-color: var(--sl-color-accent);
		font-weight: 600;
	}
	.mt-tabs .mt-tabs__home {
		margin-inline-start: auto;
	}
</style>
---
// Layout for the pages outside the docs: home, sponsor, contributors, manifesto and the tools. Same tokens,
// fonts and theme switch as the docs, with a marketing header and footer.
import '../styles/theme.css';
import '../styles/site.css';
import Analytics from '../components/Analytics.astro';
import ThemeToggle from '../components/ThemeToggle.astro';
import { CARD_HEIGHT, CARD_WIDTH, cardPath, cardUrl, defaultCard } from '../lib/og.mjs';

interface Props {
	title: string;
	description: string;
	image?: string;
	/** Wider content for tools like the test builder. */
	wide?: boolean;
	jsonLd?: Record<string, unknown>;
	/** Keep the page out of search engines (lists that only repeat other pages' titles). */
	noindex?: boolean;
}
const { title, description, image, wide = false, jsonLd, noindex = false } = Astro.props;
// Astro.url ends in .html at build time (build.format 'file'); the site serves pages without it.
const pagePath = Astro.url.pathname.replace(/(index)?\.html$/, '').replace(/\/$/, '') || '/';
const canonical = pagePath === '/' ? 'https://maester.dev/' : new URL(pagePath, Astro.site).href;
const fullTitle = pagePath === '/' ? title : `${title} | Maester`;
const nav = [
	{ label: 'Docs', href: '/docs/intro' },
	{ label: 'Test catalog', href: '/docs/tests' },
	{ label: 'Packs', href: '/docs/packs' },
	{ label: 'Blog', href: '/blog' },
	{ label: 'Contributors', href: '/contributors' },
	{ label: 'Pricing', href: '/pricing' },
	{ label: 'Maester Cloud ↗', href: 'https://maester.cloud' },
];
const path = pagePath;
// A page's own image when it passes one; otherwise its card (scripts/og-images.mjs renders it after the build). The
// home page's card is the site's own; the pages kept out of search share it.
const section = pagePath.startsWith('/blog') ? 'Blog' : pagePath.startsWith('/contributors') ? 'Contributors' : pagePath === '/sponsor' ? 'Sponsor' : pagePath === '/pricing' ? 'Pricing' : undefined;
const card = pagePath === '/' ? { ...defaultCard, path: 'index' } : noindex ? defaultCard : { path: cardPath(pagePath), label: section, title, description };
const ogImage = image ? new URL(image, Astro.site).href : cardUrl(card);
---

<!doctype html>
<html lang="en" data-theme="dark">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width, initial-scale=1" />
		<title>{fullTitle}</title>
		<meta name="description" content={description} />
		<link rel="canonical" href={canonical} />
		{noindex && <meta name="robots" content="noindex" />}
		<link rel="icon" href="/favicon.ico" sizes="32x32" />
		<link rel="icon" href="/icon-192.png" type="image/png" sizes="192x192" />
		<link rel="apple-touch-icon" href="/apple-touch-icon.png" />
		<link rel="manifest" href="/site.webmanifest" />
		<link rel="sitemap" href="/sitemap-index.xml" />
		<meta property="og:title" content={fullTitle} />
		<meta property="og:description" content={description} />
		<meta property="og:url" content={canonical} />
		<meta property="og:type" content="website" />
		<meta property="og:image" content={ogImage} />
		{!image && <meta property="og:image:width" content={String(CARD_WIDTH)} />}
		{!image && <meta property="og:image:height" content={String(CARD_HEIGHT)} />}
		<meta property="og:image:alt" content={title} />
		<meta name="twitter:card" content="summary_large_image" />
		<meta name="twitter:image" content={ogImage} />
		{!noindex && <meta name="robots" content="max-image-preview:large" />}
		{!image && !noindex && <meta name="maester:og" content={JSON.stringify(card)} />}
		{jsonLd && <script type="application/ld+json" set:html={JSON.stringify(jsonLd).replace(/</g, '\\u003c')} />}
		<script is:inline>
			// The same theme setting as the docs (Starlight keeps it in localStorage as starlight-theme).
			(function () {
				var stored = null;
				try {
					stored = localStorage.getItem('starlight-theme');
				} catch (e) {}
				var theme = stored === 'light' || stored === 'dark' ? stored : matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
				document.documentElement.dataset.theme = theme;
				document.documentElement.dataset.themeSetting = stored === 'light' || stored === 'dark' ? stored : 'system';
				var channel = null;
				try {
					channel = localStorage.getItem('maester-channel');
				} catch (e) {}
				document.documentElement.dataset.channel = channel === 'stable' ? 'stable' : 'preview';
			})();
		</script>
		<Analytics />
	</head>
	<body>
		<a class="skip" href="#main">Skip to content</a>
		<header class="site-header">
			<div class="site-header__inner">
				<a href="/" class="site-logo" aria-label="Maester home">
					<img src="/img/logo.svg" alt="" width="28" height="28" />
					<span>Maester</span>
				</a>
				<nav aria-label="Main" class="site-nav">
					{nav.map((item) => <a href={item.href} aria-current={path.startsWith(item.href) ? 'page' : undefined}>{item.label}</a>)}
				</nav>
				<div class="site-header__right">
					<a class="site-btn site-btn--ghost site-sponsor" href="/sponsor">
						<svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path fill="#db2777" d="M8 14.25s-6-3.6-6-8.1C2 3.8 3.7 2.5 5.4 2.5c1.2 0 2.1.7 2.6 1.6.5-.9 1.4-1.6 2.6-1.6 1.7 0 3.4 1.3 3.4 3.65 0 4.5-6 8.1-6 8.1z"></path></svg>
						Sponsor
					</a>
					<a class="site-icon-btn" href="https://github.com/maester365/maester" aria-label="Maester on GitHub" title="Maester on GitHub">
