content.content:
1	<!doctype html>
2	<!--
3	  Explainer: how Maester works. A HyperFrames composition (https://hyperframes.heygen.com): install, connect,
4	  Invoke-Maester with the Zero Trust Assessment pack, the console while it runs, and the report it writes.
5	  Voice-over by Kokoro and an original music bed, mixed into audio/mix.mp3 (website/scripts/narration); chapter times come from timings.js,
6	  which narrate.mjs writes. The report views are captures of the real report (scripts/capture-demo-report.mjs).
7	  The console is drawn here in HTML after Maester's own dashboard (src/Maester.Engine/MtConsoleRenderer*.cs).
8	  Watches: powershell/public/run/Invoke-Maester.ps1, powershell/public/connect/Connect-Maester.ps1,
9	  src/Maester.Engine/MtConsoleRenderer.cs, report/src/
10	-->
11	<html lang="en">
12	  <head>
13	    <meta charset="UTF-8" />
14	    <meta name="viewport" content="width=1920, height=1080" />
15	    <meta name="robots" content="noindex" />
16	    <title>How Maester works (explainer)</title>
17	    <link rel="stylesheet" href="../_shared/explainer.css" />
18	    <script src="../_shared/gsap.min.js"></script>
19	    <script src="../_shared/hyperframe.runtime.js"></script>
20	    <script src="timings.js"></script>
21	    <style>
22	      .scene { position: absolute; inset: 0; opacity: 0; }
23	      .mono { font-family: "Geist Mono", ui-monospace, Menlo, monospace; }
24	
25	      /* Intro and end card */
26	      .center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 34px; }
27	      .flame { width: 120px; height: 140px; }
28	      .big { font-size: 92px; font-weight: 700; letter-spacing: -0.035em; line-height: 1.04; max-width: 1500px; }
29	      .ember { color: #ff6b6f; }
30	      .sub { font-size: 38px; color: #a1a1aa; }
31	      .pill { font-family: "Geist Mono", monospace; font-size: 34px; background: #18181b; border: 2px solid #27272a; border-radius: 18px; padding: 22px 36px; color: #e4e4e7; }
32	      .pill b { color: #ff8a8d; font-weight: 500; }
33	      .chips { display: flex; gap: 20px; }
34	      .chip { font-size: 30px; border: 2px solid #3f3f46; border-radius: 999px; padding: 12px 28px; color: #d4d4d8; }
35	
36	      /* Terminal */
