p='public/explainers/how-it-works/index.html'
s=open(p).read()
rep=[
# css
("""      .chips { display: flex; gap: 20px; }""",
"""      .chips { display: flex; gap: 20px; }
      /* Intro: the flame's glow, the headline's words, and the products ticking over as they are named */
      .flamewrap { position: relative; width: 120px; height: 140px; }
      .glow { position: absolute; left: 50%; top: 55%; width: 520px; height: 520px; margin: -260px 0 0 -260px; border-radius: 50%; background: radial-gradient(closest-side, rgba(255,95,95,.34), rgba(255,95,95,0)); opacity: 0; }
      .flamewrap .flame { position: relative; transform-origin: 50% 90%; }
      .big .w { display: inline-block; opacity: 0; }
      .underline { position: relative; display: inline-block; }
      .underline::after { content: ""; position: absolute; left: 0; right: 0; bottom: -4px; height: 8px; border-radius: 4px; background: #ff6b6f; transform: scaleX(var(--u, 0)); transform-origin: 0 50%; }
      .products { display: flex; gap: 16px; }
      .product { display: flex; align-items: center; gap: 12px; font-size: 28px; border: 2px solid #27272a; border-radius: 999px; padding: 10px 24px 10px 14px; color: #a1a1aa; background: #111113; opacity: 0; }
      .product i { position: relative; width: 30px; height: 30px; border-radius: 50%; border: 2px solid #3f3f46; display: block; }
      .product i::after { content: "✓"; position: absolute; inset: -2px; border-radius: 50%; background: #22c55e; color: #052e16; font-style: normal; font-weight: 700; font-size: 20px; line-height: 30px; text-align: center; opacity: var(--tick, 0); transform: scale(var(--tick, 0)); }
      #s-intro .sub { opacity: 0; }"""),
# markup
("""          <svg class="flame" viewBox="0 0 24 28" aria-hidden="true"><path d="M12 1c1.4 4-1.2 6.4-2.6 8.3C7.6 11.6 6 13.6 6 16.6 6 21 8.7 25 12 25s6-3.1 6-7.4c0-2.3-.9-4-2.1-5.4.2 1.9-.7 3.4-2 3.8.7-4.2-.4-10.3-1.9-15z" fill="#ff5f5f"></path><path d="M12 25c-1.9 0-3.2-1.6-3.2-3.6 0-2 1.6-3.2 2.4-4.6.6 1.4 2 2 2 4 .6-.4 1-1.1 1.2-1.8.5.7.8 1.5.8 2.4 0 2-1.4 3.6-3.2 3.6z" fill="#ffb347"></path></svg>
          <div class="big">Test your Microsoft 365 <span class="ember">security</span>,<br />every day, in one run.</div>
          <div class="sub">Maester · open source · free</div>""",
"""          <div class="flamewrap">
            <div class="glow"></div>
            <svg class="flame" viewBox="0 0 24 28" aria-hidden="true"><path d="M12 1c1.4 4-1.2 6.4-2.6 8.3C7.6 11.6 6 13.6 6 16.6 6 21 8.7 25 12 25s6-3.1 6-7.4c0-2.3-.9-4-2.1-5.4.2 1.9-.7 3.4-2 3.8.7-4.2-.4-10.3-1.9-15z" fill="#ff5f5f"></path><path d="M12 25c-1.9 0-3.2-1.6-3.2-3.6 0-2 1.6-3.2 2.4-4.6.6 1.4 2 2 2 4 .6-.4 1-1.1 1.2-1.8.5.7.8 1.5.8 2.4 0 2-1.4 3.6-3.2 3.6z" fill="#ffb347"></path></svg>
          </div>
          <div class="sub">Maester · open source · free</div>
          <div class="big">
            <span class="w l1">Test</span> <span class="w l1">your</span> <span class="w l1">Microsoft</span> <span class="w l1">365</span> <span class="w l1 ember">security,</span><br />
            <span class="w l2 underline" id="u-day">every day,</span> <span class="w l3 underline" id="u-run">in one run.</span>
          </div>
          <div class="products">
            <span class="product"><i></i>Entra ID</span><span class="product"><i></i>Exchange</span><span class="product"><i></i>Teams</span><span class="product"><i></i>SharePoint</span><span class="product"><i></i>Defender</span><span class="product"><i></i>Intune</span><span class="product"><i></i>Azure</span>
          </div>"""),
# timeline
("""      show("#s-intro", 0, 0.4);
      tl.from("#s-intro .big", { y: 40, duration: 1 }, 0);
      hide("#s-intro", C.install.t - 0.6);""",
"""      // Something moves the whole time, in step with the voice-over, so the opening reads without sound: the flame
      // lights, the name, the headline a phrase at a time as it is spoken, and each product ticking over.
      const t0 = C.intro.t;
      const at = (part) => t0 + C.intro.length * part; // a point in the spoken sentence, 0 to 1
      show("#s-intro", 0, 0.3);
      tl.fromTo("#s-intro .flame", { scale: 0.2, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.9, ease: "back.out(2)" }, 0.1);
      tl.fromTo("#s-intro .glow", { opacity: 0, scale: 0.4 }, { opacity: 1, scale: 1, duration: 1.2, ease: "power2.out" }, 0.2);
      tl.to("#s-intro .glow", { scale: 1.18, opacity: 0.7, duration: 0.9, ease: "sine.inOut", repeat: 7, yoyo: true }, 1.4);
      tl.to("#s-intro .flame", { scaleY: 1.07, scaleX: 0.97, duration: 0.45, ease: "sine.inOut", repeat: 15, yoyo: true }, 1.1);
      tl.fromTo("#s-intro .sub", { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: 0.6 }, at(0.08));
      tl.fromTo("#s-intro .l1", { opacity: 0, y: 36 }, { opacity: 1, y: 0, duration: 0.5, stagger: 0.24, ease: "power2.out" }, at(0.32));
      tl.fromTo("#s-intro .product", { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.4, stagger: 0.14, ease: "power2.out" }, at(0.36));
      tl.to("#s-intro .product i", { "--tick": 1, duration: 0.3, stagger: 0.3, ease: "back.out(2)" }, at(0.5));
      tl.to("#s-intro .product", { color: "#fafafa", borderColor: "#3d6b3d", duration: 0.3, stagger: 0.3 }, at(0.5));
      tl.fromTo("#s-intro .l2", { opacity: 0, y: 36 }, { opacity: 1, y: 0, duration: 0.5, ease: "power2.out" }, at(0.7));
      tl.to("#u-day", { "--u": 1, duration: 0.5, ease: "power2.out" }, at(0.74));
      tl.fromTo("#s-intro .l3", { opacity: 0, y: 36 }, { opacity: 1, y: 0, duration: 0.5, ease: "power2.out" }, at(0.85));
      tl.to("#u-run", { "--u": 1, duration: 0.5, ease: "power2.out" }, at(0.89));
      hide("#s-intro", C.install.t - 0.6);"""),
]
for o,n in rep:
    assert o in s, o[:60]
    s=s.replace(o,n,1)
open(p,'w').write(s)
EOF
