css=r'''	/* The Cloud button. At rest a slow ember ring turns around it. Under the pointer the ring speeds up and glows, the
	   button leans towards the cursor, a light follows the cursor across it and the arrow leans in. A click squeezes it
	   and throws embers and green ticks from the pointer (the script below), then opens the link. */
	@property --cta-angle {
		syntax: '<angle>';
		inherits: false;
		initial-value: 0deg;
	}
	.cloud-cta-wrap {
		position: relative;
		display: flex;
		margin-top: auto;
		border-radius: 12px;
		transform: translate(var(--tx, 0px), var(--ty, 0px));
