// The check counts the explainer videos show in their terminal (public/explainers/how-it-works loads this as
// ../counts.js), from the same module as the pages, so the video can't disagree with them. Played outside the site
// (npx hyperframes preview) the file isn't there, and the numbers in the composition's markup stand.
import type { APIRoute } from 'astro';
import { builtIn, core, zta } from '../../lib/check-counts';

export const GET: APIRoute = () =>
	new Response(`window.__counts = ${JSON.stringify({ builtIn, zta, core })};\n`, {
		headers: { 'Content-Type': 'text/javascript; charset=utf-8' },
	});
EOF
python3 - <<'EOF'
p='public/explainers/how-it-works/index.html'
s=open(p).read()
o='    <!-- The live check counts (scripts/prepare-data.mjs). Without the file the numbers in the markup stand. -->\n    <script src="../_shared/counts.js"></script>\n'
assert o in s
s=s.replace(o,'    <!-- The live check counts, served by the site (src/pages/explainers/counts.js.ts). Without it the numbers in\n         the markup stand. -->\n    <script src="../counts.js"></script>\n')
open(p,'w').write(s)
p='src/lib/check-counts.ts'
s=open(p).read()
o="// How many checks Maester has, counted once for every page that says so (the home page and the pricing page), so the"
assert o in s
s=s.replace(o,"// How many checks Maester has, counted once for every page that says so (the home page, the pricing page and the\n// explainer video, through pages/explainers/counts.js.ts), so the")
open(p,'w').write(s)
EOF
